import type { IsoTimestamp, OrgId, UserId } from "./common";

/** `read` tokens act as a viewer; `write` tokens act with the member's role. */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the app sees it. Never carries the secret or its
 * hash — the secret is returned once, from `createApiToken`, and only its
 * hash is stored.
 */
