/**
 * Personal API tokens, keyed by token hash for authentication. Only the hash
 * of the secret is ever stored.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  readonly createdAt: IsoTimestamp;
}

function usablePredicate(orgId: OrgId, userId: UserId, now: IsoTimestamp) {
  return and(
    orgPredicate(apiTokens.orgId, orgId),
    eq(apiTokens.userId, userId),
    isNull(apiTokens.revokedAt),
    gt(apiTokens.expiresAt, now),
  );
}

/** Tokens that are neither revoked nor expired at `now`. */
export async function countUsableApiTokens(
  orgId: OrgId,
  userId: UserId,
  now: IsoTimestamp,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(apiTokens)
    .where(usablePredicate(orgId, userId, now))
    .get();
  return row?.value ?? 0;
}

/**
 * Inserts a token unless the user already holds `limit` usable ones in the
 * org. The count and the insert share one transaction so concurrent creates
 * cannot overshoot the allowance. Returns `null` when the limit is reached.
 */
export async function insertApiTokenWithinLimit(
  orgId: OrgId,
  input: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  const db = getDb();
  return db.transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(usablePredicate(orgId, input.userId, input.createdAt))
      .get();
    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
        updatedAt: input.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * Authentication runs before an `Actor` exists, so — like the invitation
 * accept flow — this read is not scoped by `orgId`: the token hash is the
 * credential and carries the tenant with it.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Every token of the user in the org, revoked and expired included, newest first. */
export async function listApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)))
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all();
  return rows.map(toApiToken);
}

/** Tokens of the user in the org that have not been revoked yet (expired included). */
export async function listUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all();
  return rows.map(toApiToken);
}

/**
 * Sets `revokedAt` unless the token is already revoked. Returns the updated
 * token, or `null` when nothing changed (unknown or already revoked).
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}
