/**
 * Personal API tokens: minting, listing, revocation and bearer authentication for scripts and CI.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, resolveActor
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so leaked tokens are easy to scan for. */
const TOKEN_PREFIX = "tfk_";

/** How many characters of the secret are kept in clear as `prefix`. */
const DISPLAY_PREFIX_LENGTH = 12;

/** Usable (unrevoked, unexpired) tokens a user may hold per organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token. The secret is returned here and nowhere else — only its
 * hash is stored, and `ApiToken` never carries either.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const now = new Date();
  const token = `${TOKEN_PREFIX}${randomToken(32)}`;

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    parsed.orgId,
    {
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );

  if (!apiToken) {
    throw new Error(
      `A member may hold at most ${MAX_USABLE_TOKENS} active API tokens per organization; revoke one first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    occurredAt: apiToken.createdAt,
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/** A user's tokens in the org, revoked and expired included, newest first. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokensForUser(orgId, userId);
}

/**
 * Revokes one token. Idempotent: an already-revoked token comes back
 * unchanged and nothing new is audited.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );

  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  if (existing.revokedAt !== null) return existing;

  const revoked = await revokeAndAnnounce(orgId, tokenId, actor.userId);
  if (revoked) return revoked;

  // Lost a race with another revocation; report the row as it now stands.
  return requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
}

