 * Turns a bearer secret into the `Actor` it acts as, or `null` when the token
 * is unknown, revoked, expired, its org is gone, or its user is no longer an
 * active member. A `read` token always acts as a viewer; a `write` token acts
 * with the member's current role.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  if (typeof token !== "string" || !token.startsWith(TOKEN_PREFIX)) {
    return null;
  }

  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (!apiToken) return null;

  const now = new Date();
  if (apiToken.revokedAt !== null) return null;
  if (now.getTime() >= Date.parse(apiToken.expiresAt)) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (!member) return null;

  await apiTokenRepo.touchApiTokenLastUsed(
    apiToken.orgId,
    apiToken.id,
    toIsoTimestamp(now),
  );

  return {
    userId: member.userId,
    orgId: member.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

