 * Revokes every not-yet-revoked token the user holds in the org (expired ones
 * included), auditing each with `actorId` as the revoker.
 */
export async function revokeAllApiTokensForMember(
  orgId: OrgId,
  userId: UserId,
  actorId: UserId | null,
): Promise<readonly ApiToken[]> {
  const pending = await apiTokenRepo.listUnrevokedApiTokensForUser(orgId, userId);
  const revoked: ApiToken[] = [];

  for (const token of pending) {
    const row = await revokeAndAnnounce(orgId, token.id, actorId);
    if (row) revoked.push(row);
  }

  return revoked;
}

/**
 * Attaches the token lifecycle to membership changes: a removed member's
 * tokens in that org stop working the moment they leave. Called once from
 * `event-registry`.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    await revokeAllApiTokensForMember(
      payload.orgId,
      payload.userId,
      payload.actorId,
    );
  });
}

/** Revokes if still live and publishes `api_token.revoked`; `null` if already revoked. */
async function revokeAndAnnounce(
  orgId: OrgId,
  tokenId: string,
  actorId: UserId | null,
): Promise<ApiToken | null> {
  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );
  if (!revoked) return null;

  await emit("api_token.revoked", {
    ...envelope(orgId, actorId),
    occurredAt: revoked.revokedAt ?? toIsoTimestamp(new Date()),
    tokenId: revoked.id,
    userId: revoked.userId,
    name: revoked.name,
  });

  return revoked;
}

