cat > tests/server/zz-scratch-api-token.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";
import { registerEventHandlers } from "@/server/services/event-registry";
import * as svc from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { getDb } from "@/server/db";
import { activityFilterSchema } from "@/schemas/activity";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

describe("api tokens", () => {
  it("works", async () => {
    const t = await createTenant("tok");
    const t2 = await createTenant("tok2");
    const m = t.actors.member;
    await expect(svc.createApiToken(m, { orgId: t.org.id, name: " ", scope: "read", expiresInDays: 1 })).rejects.toBeInstanceOf(ZodError);
    await expect(svc.createApiToken(m, { orgId: t2.org.id, name: "x", scope: "read", expiresInDays: 1 })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(svc.createApiToken(t.actors.viewer, { orgId: t.org.id, name: "x", scope: "write", expiresInDays: 1 })).rejects.toBeInstanceOf(PermissionDeniedError);
    const { token, apiToken } = await svc.createApiToken(m, { orgId: t.org.id, name: "  ci  ", scope: "write", expiresInDays: 30 });
    expect(token.startsWith("tfk_")).toBe(true);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("ci");
    expect(Object.keys(apiToken).sort()).toEqual(["createdAt","expiresAt","id","lastUsedAt","name","orgId","prefix","revokedAt","scope","userId"]);
    expect(Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt)).toBe(30 * 86400000);
    for (let i = 0; i < 4; i++) await svc.createApiToken(m, { orgId: t.org.id, name: `t${i}`, scope: "read", expiresInDays: 1 });
    await expect(svc.createApiToken(m, { orgId: t.org.id, name: "six", scope: "read", expiresInDays: 1 })).rejects.toThrow();
    const list = await svc.listApiTokens(m, t.org.id);
    expect(list.map((x) => x.name)).toEqual(["t3", "t2", "t1", "t0", "ci"]);
    await expect(svc.listApiTokens(m, t.org.id, t.userIds.admin)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await svc.listApiTokens(t.actors.admin, t.org.id, m.userId)).toHaveLength(5);

    const actor = await svc.authenticateApiToken(token);
    expect(actor).toEqual({ userId: m.userId, orgId: t.org.id, role: "member" });
    expect((await svc.listApiTokens(m, t.org.id)).find((x) => x.id === apiToken.id)?.lastUsedAt).not.toBeNull();
    await expect(svc.revokeApiToken(m, t.org.id, "nope")).rejects.toBeInstanceOf(NotFoundError);
    await expect(svc.revokeApiToken(t.actors.viewer, t.org.id, apiToken.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    const r1 = await svc.revokeApiToken(m, t.org.id, apiToken.id);
    const r2 = await svc.revokeApiToken(t.actors.owner, t.org.id, apiToken.id);
    expect(r2.revokedAt).toBe(r1.revokedAt);
    expect(await svc.authenticateApiToken(token)).toBeNull();
    await svc.createApiToken(m, { orgId: t.org.id, name: "again", scope: "read", expiresInDays: 1 });

    const member = await memberRepo.findMember(t.org.id, m.userId);
    await memberService.removeMember(t.actors.admin, { orgId: t.org.id, memberId: member!.id } as never);
    const after = await svc.listApiTokens(t.actors.admin, t.org.id, m.userId);
    expect(after.every((x) => x.revokedAt !== null)).toBe(true);
    const rows = getDb().$client.prepare("select * from activity_events where subject_kind='api_token'").all() as any[];
    expect(rows.filter((r) => r.action === "api_token.created")).toHaveLength(6);
    expect(rows.filter((r) => r.action === "api_token.revoked")).toHaveLength(6);
    expect(JSON.stringify(rows)).not.toContain(token);
    expect(activityFilterSchema.parse({ orgId: t.org.id, action: ["api_token.revoked"], subjectKind: "api_token" }).subjectKind).toBe("api_token");

    const { token: rt } = await svc.createApiToken(t.actors.admin, { orgId: t.org.id, name: "r", scope: "read", expiresInDays: 1 });
    expect((await svc.authenticateApiToken(rt))?.role).toBe("viewer");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(Date.now() + 86400000);
    expect(await svc.authenticateApiToken(rt)).toBeNull();
    vi.useRealTimers();
    await orgRepo.archiveOrg(t.org.id);
    const { token: wt } = await svc.createApiToken(t2.actors.admin, { orgId: t2.org.id, name: "w", scope: "write", expiresInDays: 1 });
    expect((await svc.authenticateApiToken(wt))?.role).toBe("admin");
  });
});
EOF
npx vitest run tests/server/zz-scratch-api-token.test.ts 2>&1 | tail -30

